#!/usr/bin/env python3\n"""Fail closed if browser-derived values regain raw Nix source interpolation."""\n\nfrom pathlib import Path\nimport sys\n\nSECURITY = Path("crates/domains/symthaea-spore/src/security.rs")\nRELAY = Path("crates/domains/symthaea-spore/src/bin/ssh_relay.rs")\n\ndef fail(message: str) -> None:\n    print(f"nix-codegen-boundary: FAIL: {message}", file=sys.stderr)\n    raise SystemExit(1)\n\ndef require(text: str, needle: str, description: str) -> None:\n    if needle not in text:\n        fail(f"{description}: missing {needle!r}")\n\ndef case_body(text: str, name: str) -> str:\n    start = text.find(f'            "{name}" => {{')\n    if start < 0:\n        fail(f"mutation arm {name!r} disappeared")\n    end = text.find("\n            \"", start + 20)\n    return text[start:] if end < 0 else text[start:end]\n\ndef main() -> None:\n    if not SECURITY.is_file() or not RELAY.is_file():\n        fail("expected security/codegen source files are missing")\n\n    security = SECURITY.read_text(encoding="utf-8")\n    relay = RELAY.read_text(encoding="utf-8")\n\n    require(security, "pub fn nix_string_literal(value: &str) -> String", "Nix literal renderer")\n    require(security, "nix_string_literal_escapes_quotes_backslashes_and_interpolation", "literal adversarial regression")\n    require(security, "\'$\' if chars.peek() == Some(&\'{\')", "Nix interpolation escape")\n\n    generator_start = relay.find("fn generate_system_config(msg: &ClientMessage) -> String {")\n    generator_end = relay.find("fn single_luks_fallback_configuration", generator_start)\n    if generator_start < 0 or generator_end < 0:\n        fail("generate_system_config boundary disappeared")\n    generator = relay[generator_start:generator_end]\n    require(generator, "let tz_literal = nix_string_literal(&tz);", "timezone literal sink")\n    require(generator, "let kb_literal = nix_string_literal(&kb);", "keyboard literal sink")\n    if "time.timeZone = \\"{}\\"" in generator or "console.keyMap = \\"{}\\"" in generator:\n        fail("generated Nix contains raw format-string value interpolation")\n\n    fallback_start = relay.find("fn single_luks_fallback_configuration(hostname: &str) -> String {")\n    fallback_end = relay.find("fn generate_system_config_module", fallback_start)\n    if fallback_start < 0 or fallback_end < 0:\n        fail("single_luks_fallback_configuration boundary disappeared")\n    fallback = relay[fallback_start:fallback_end]\n    require(fallback, "let hostname_literal = nix_string_literal(hostname);", "hostname literal sink")\n    require(fallback, 'users.users.__HOSTNAME_ATTR__ = {', "hostname attribute placeholder")\n    require(fallback, 'config.replace("__HOSTNAME_ATTR__", &hostname_literal)', "quoted hostname attribute replacement")\n    if "users.users.__HOSTNAME__" in fallback:\n        fail("hostname is still interpolated as an unquoted Nix identifier")\n\n    for arm in ("install", "write_config"):\n        body = case_body(relay, arm)\n        if "generate_system_config(" in body and "nix_string_literal" not in relay:\n            fail(f"mutation arm {arm!r} can generate Nix without the literal renderer")\n\n    print("nix-codegen-boundary: PASS: generated Nix sinks use centralized literal escaping")\n\nif __name__ == "__main__":\n    main()\n